set local session_replication_role = origin;
do $$ declare r record; begin
  for r in select table_schema, table_name, column_name from information_schema.columns
           where table_schema = 'public' and is_identity = 'YES' loop
    execute format('select setval(pg_get_serial_sequence(%L, %L), greatest(coalesce((select max(%I) from %I.%I), 0), 1))',
      r.table_schema || '.' || r.table_name, r.column_name, r.column_name, r.table_schema, r.table_name);
  end loop;
end $$;
